// Styles
import '@/styles/globals.scss';

import { ClerkProvider } from '@clerk/nextjs';
import { Analytics } from '@vercel/analytics/next';
import { generateMetadata } from '@/lib/seo';
import ClerkAuthBridge from '@/components/ClerkAuthBridge';
import Header from '@/components/layout/Header';
import Footer from '@/components/layout/Footer';
import { CLERK_APPEARANCE } from '@/lib/clerk';
import { PropsWithChildren } from 'react';
import type { Viewport } from 'next';

/**
 * Global metadata configuration for the entire site.
 * Generated by utility function for consistency and reusability.
 */
export const metadata = generateMetadata({ isRootLayout: true });

// Keep browser zoom available. Board-local handlers own game pan and pinch.
export const viewport: Viewport = {
  width: 'device-width',
  initialScale: 1,
};

export default function RootLayout({ children }: PropsWithChildren) {
  return (
    <ClerkProvider appearance={CLERK_APPEARANCE}>
      <html lang="en">
        <body>
          <div id="root">
            <ClerkAuthBridge />
            <Header />

            {children}

            <Footer />
          </div>
          <Analytics />
        </body>
      </html>
    </ClerkProvider>
  );
}
